window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4788a211d48103a8"]={"versions": [{"id": "FIG-4788a211d48103a8", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-Konfigurationsmetamodells (ECU Configuration Parameter Definition) für das BSW-Modul DCM (Diagnostic Communication Manager), spezifisch für OBD Service $09 (Request Vehicle Information) innerhalb des Submoduls <code>DcmDsp</code>. Das Diagramm ist in einen äußeren Rahmen mit dem Header <code>class DcmDspVehInfo</code> eingefasst.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert Konfigurationscontainer und zugeordnete Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>DcmDsp : ParamConfContainerDef</code>: Übergeordneter Konfigurationscontainer mit Multiplizität 1..1.</li>\n<li><code>DcmDspVehInfo : ParamConfContainerDef</code>: Untergeordneter Konfigurationscontainer (<code>+subContainer</code>), aggregiert über eine Kompositionsbeziehung durch <code>DcmDsp</code>, mit Multiplizität 0..<em> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = </em></code>).</li>\n<li>Enthaltene Parameter (<code>+parameter</code>, aggregiert via Komposition durch <code>DcmDspVehInfo</code>):</li>\n<li><code>DcmDspVehInfoInfoType : IntegerParamDef</code>: Multiplizität 1..1, Wertebereich <code>min = 0</code>, <code>max = 255</code>.</li>\n<li><code>DcmDspVehInfoSize : IntegerParamDef</code>: Multiplizität 1..1, Wertebereich <code>min = 0</code>, <code>max = 255</code>.</li>\n<li><code>DcmDspGetVehInfoTypeFnc : FunctionNameDef</code>: Multiplizität 1..1.</li>\n<li><code>DcmDspVehInfoUsePort : BooleanParamDef</code>: Multiplizität 1..1.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur definiert statische Validierungs- und Generierungsregeln für die BSW-Konfiguration zur Build- bzw. Generierungszeit des DCM.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für die Parametrierung von OBD Service $09:</p>\n<ul class=\"fig-list\">\n<li>Jede konfigurierte Fahrzeuginformation (<code>DcmDspVehInfo</code>) spezifiziert genau einen InfoType (<code>DcmDspVehInfoInfoType</code>, 1 Byte / 0..255) sowie die zugehörige Datengröße (<code>DcmDspVehInfoSize</code>, 1 Byte / 0..255).</li>\n<li>Über <code>DcmDspVehInfoUsePort</code> wird festgelegt, ob der Zugriff über Ports (AUTOSAR-Schnittstelle) oder über eine C-Callback-Funktion (<code>DcmDspGetVehInfoTypeFnc</code>) erfolgt; beide Parameter müssen auf Metamodell-Ebene mit Kardinalität 1..1 instanziiert werden.</li>\n</ul>"}, {"id": "FIG-c31b9247a800d9a6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-Konfigurationsmetamodells (ECU Configuration Parameter Definition) für das BSW-Modul DCM (Diagnostic Communication Manager), spezifisch für OBD Service $09 (Request Vehicle Information) innerhalb des Submoduls <code>DcmDsp</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert Konfigurationscontainer und zugeordnete Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>DcmDsp : ParamConfContainerDef</code>: Übergeordneter Konfigurationscontainer mit Multiplizität 1..1.</li>\n<li><code>DcmDspVehInfo : ParamConfContainerDef</code>: Untergeordneter Konfigurationscontainer (<code>+subContainer</code>), aggregiert über eine Kompositionsbeziehung durch <code>DcmDsp</code>, mit Multiplizität 0..<em> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = </em></code>).</li>\n<li>Enthaltene Parameter (<code>+parameter</code>, aggregiert via Komposition durch <code>DcmDspVehInfo</code>):</li>\n<li><code>DcmDspVehInfoInfoType : IntegerParamDef</code>: Multiplizität 1..1, Wertebereich <code>min = 0</code>, <code>max = 255</code>.</li>\n<li><code>DcmDspVehInfoSize : IntegerParamDef</code>: Multiplizität 1..1, Wertebereich <code>min = 0</code>, <code>max = 255</code>.</li>\n<li><code>DcmDspGetVehInfoTypeFnc : FunctionNameDef</code>: Multiplizität 1..1.</li>\n<li><code>DcmDspVehInfoUsePort : BooleanParamDef</code>: Multiplizität 1..1.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Verhaltens- oder Sequenzdarstellung. Die Struktur definiert statische Validierungs- und Generierungsregeln für die BSW-Konfiguration zur Build- bzw. Generierungszeit des DCM.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für die Parametrierung von OBD Service $09:</p>\n<ul class=\"fig-list\">\n<li>Jede konfigurierte Fahrzeuginformation (<code>DcmDspVehInfo</code>) spezifiziert genau einen InfoType (<code>DcmDspVehInfoInfoType</code>, 1 Byte / 0..255) sowie die zugehörige Datengröße (<code>DcmDspVehInfoSize</code>, 1 Byte / 0..255).</li>\n<li>Über <code>DcmDspVehInfoUsePort</code> wird festgelegt, ob der Zugriff über Ports (AUTOSAR-Schnittstelle) oder über eine C-Callback-Funktion (<code>DcmDspGetVehInfoTypeFnc</code>) erfolgt; beide Parameter müssen auf Metamodell-Ebene mit Kardinalität 1..1 instanziiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-4788a211d48103a8", "to": "FIG-c31b9247a800d9a6", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammumrahmung: Der äußere UML-Diagrammrahmen mit dem Kopf <code>class DcmDspVehInfo</code> wurde entfernt.</li>\n<li>Anordnung von Metadatenfeldern: In den Attributbereichen der Container und Parameter wurden die Zeilen für Multiplizitäten (<code>lowerMultiplicity</code>, <code>upperMultiplicity</code>) sowie Wertebereiche (<code>min</code>, <code>max</code>) in der Reihenfolge redaktionell umgeordnet.</li>\n</ul>"}]};
